import $ from '@fr0st/query';
import { BaseComponent } from '@fr0st/ui';
import { getValidCharacters } from './helpers.js';

/**
 * @typedef {object} AuthCodeInputOptions
 * @property {boolean} [autoSubmit=false] Whether to submit the containing form when the code is complete.
 * @property {((index: number) => string)} [getAriaLabel] Generates the accessible label for a character input.
 * @property {number|number[]} [length] The character count, or the character counts for divided segments.
 * @property {string} [regExp='[0-9]'] The regular expression used to validate each character.
 * @property {'filled'|'outline'} [style='outline'] The Frost UI input style.
 */

/**
 * Controls a segmented authentication code input.
 * @augments {BaseComponent<AuthCodeInputOptions>}
 */
export default class AuthCodeInput extends BaseComponent {
    static classes = {
        container: 'd-flex justify-content-between',
        divider: 'vr align-self-center fs-5',
        hide: 'visually-hidden',
        input: 'fw-bold text-center px-0',
        inputContainer: 'form-input w-auto',
    };
    /** @type {AuthCodeInputOptions} */
    static defaults = {
        style: 'outline',
        length: [3, 3],
        regExp: '[0-9]',
        autoSubmit: false,
        getAriaLabel: (i) => `Character ${i}`,
    };

    #container;
    #form;
    #hidden;
    #inputs;
    #length;
    #regExp;
    #resetHandler;
    #segments;
    #tabIndex;

    /**
     * Creates an AuthCodeInput.
     * @param {HTMLElement} node The input node.
     * @param {AuthCodeInputOptions} [options] The AuthCodeInput options.
     */
    constructor(node, options) {
        super(node, options);

        try {
            this.#form = this.node.form;

            this.#hidden = $.hasClass(this.node, this.constructor.classes.hide);
            this.#tabIndex = $.getAttribute(this.node, 'tabindex');

            this.#segments = $._wrap(this.options.length)
                .map((length) => Number.parseInt(length, 10));
            this.#length = this.#segments.reduce((total, length) => total + length, 0);

            const maxLength = Number.parseInt($.getAttribute(this.node, 'maxlength'), 10);
            if (
                Number.isInteger(maxLength) &&
                maxLength >= 0 &&
                this.#length > maxLength
            ) {
                this.#length = maxLength;
                this.#segments = [maxLength];
            }

            this.#regExp = new RegExp(this.options.regExp);

            this.#render();
            this.#events();
            this.#refresh();
            this.#refreshDisabled();
        } catch (error) {
            this.dispose();
            throw error;
        }
    }

    /**
     * Clears the AuthCodeInput.
     */
    clear() {
        this.setValue('');
    }

    /**
     * Disables the AuthCodeInput.
     */
    disable() {
        $.setAttribute(this.node, { disabled: true });
        this.#refreshDisabled();
    }

    /** @inheritdoc */
    dispose() {
        if (!this.node) {
            return;
        }

        $.remove(this.#container);
        $.removeEvent(this.node, 'focus.ui.authcodeinput');

        if (this.#form && this.#resetHandler) {
            $.removeEvent(this.#form, 'reset.ui.authcodeinput', this.#resetHandler);
        }

        if (this.#hidden) {
            $.addClass(this.node, this.constructor.classes.hide);
        } else {
            $.removeClass(this.node, this.constructor.classes.hide);
        }

        if (this.#tabIndex === null) {
            $.removeAttribute(this.node, 'tabindex');
        } else {
            $.setAttribute(this.node, { tabindex: this.#tabIndex });
        }

        this.#container = null;
        this.#form = null;
        this.#inputs = null;
        this.#regExp = null;
        this.#resetHandler = null;
        this.#segments = null;

        super.dispose();
    }

    /**
     * Enables the AuthCodeInput.
     */
    enable() {
        $.removeAttribute(this.node, 'disabled');
        this.#refreshDisabled();
    }

    /**
     * Gets the current value.
     * @returns {string} The current value.
     */
    getValue() {
        return $.getValue(this.node);
    }

    /**
     * Sets the value.
     * @param {string} value The value.
     */
    setValue(value) {
        $.setValue(this.node, value);
        this.#refresh();
    }

    /**
     * Distributes a value across the rendered inputs.
     * @param {string} value The value to distribute.
     * @param {number} startIndex The first input index.
     * @returns {boolean} Whether any valid characters were distributed.
     */
    #distributeValue(value, startIndex) {
        const chars = getValidCharacters(value, this.#regExp)
            .slice(0, this.#inputs.length - startIndex);

        if (!chars.length) {
            return false;
        }

        for (const [offset, char] of chars.entries()) {
            $.setValue(this.#inputs[startIndex + offset], char);
        }

        this.#updateValue();

        if (!this.node) {
            return true;
        }

        const focusIndex = Math.min(
            startIndex + chars.length,
            this.#inputs.length - 1,
        );
        $.focus(this.#inputs[focusIndex]);

        return true;
    }

    /**
     * Attaches events for the AuthCodeInput.
     */
    #events() {
        if (this.#form) {
            this.#resetHandler = (event) => {
                setTimeout(() => {
                    if (this.node && !event.defaultPrevented) {
                        this.#refresh();
                    }
                }, 0);
            };

            $.addEvent(this.#form, 'reset.ui.authcodeinput', this.#resetHandler);
        }

        $.addEvent(this.node, 'focus.ui.authcodeinput', () => {
            const nextInput = this.#inputs.find((input) => !$.getValue(input));
            $.focus(nextInput || this.#inputs[0]);
        });

        $.addEventDelegate(this.#container, 'focusin.ui.authcodeinput', 'input', (event) => {
            const target = event.currentTarget;
            const targetIndex = this.#inputs.indexOf(target);
            const lastIndex = this.#inputs.findLastIndex((input) => $.getValue(input));

            if (targetIndex > lastIndex + 1) {
                $.focus(this.#inputs[lastIndex + 1]);
            } else {
                $.select(target);
            }
        });

        $.addEventDelegate(this.#container, 'input.ui.authcodeinput', 'input', (event) => {
            const target = event.currentTarget;
            const targetIndex = this.#inputs.indexOf(target);
            let value = $.getValue(target);

            if (Array.from(value).length > 1) {
                if (!this.#distributeValue(value, targetIndex)) {
                    $.setValue(target, '');
                    this.#updateValue();
                }

                return;
            }

            if (value && !getValidCharacters(value, this.#regExp).length) {
                value = '';
                $.setValue(target, value);
            }

            this.#updateValue();

            if (!this.node || !value) {
                return;
            }

            if (targetIndex < this.#inputs.length - 1) {
                $.focus(this.#inputs[targetIndex + 1]);
            }
        });

        $.addEventDelegate(this.#container, 'paste.ui.authcodeinput', 'input', (event) => {
            if (this.node.readOnly) {
                return;
            }

            event.preventDefault();

            this.#distributeValue(
                event.clipboardData.getData('text'),
                this.#inputs.indexOf(event.currentTarget),
            );
        });

        $.addEventDelegate(this.#container, 'keydown.ui.authcodeinput', 'input', (event) => {
            if (event.ctrlKey || event.metaKey) {
                return;
            }

            const target = event.currentTarget;
            const targetIndex = this.#inputs.indexOf(target);

            switch (event.code) {
                case 'ArrowLeft':
                case 'ArrowRight': {
                    let offset = event.code === 'ArrowLeft' ? -1 : 1;

                    if ($.css(this.#container, 'direction') === 'rtl') {
                        offset *= -1;
                    }

                    const nextIndex = targetIndex + offset;

                    if (nextIndex < 0 || nextIndex >= this.#inputs.length) {
                        return;
                    }

                    $.focus(this.#inputs[nextIndex]);
                    break;
                }
                case 'Backspace':
                    if (this.node.readOnly) {
                        return;
                    }

                    if ($.getValue(target)) {
                        $.setValue(target, '');
                        this.#updateValue();
                    } else if (targetIndex > 0) {
                        const previousInput = this.#inputs[targetIndex - 1];
                        $.setValue(previousInput, '');
                        this.#updateValue();

                        if (this.node) {
                            $.focus(previousInput);
                        }
                    }
                    break;
                default:
                    if (event.key.length !== 1 || event.key.match(this.#regExp)) {
                        return;
                    }
                    break;
            }

            event.preventDefault();
        });
    }

    /**
     * Refreshes the rendered input values.
     */
    #refresh() {
        const chars = getValidCharacters($.getValue(this.node), this.#regExp);

        for (const [index, input] of this.#inputs.entries()) {
            $.setValue(input, chars[index] || '');
        }

        this.#updateValue({ notify: false });
    }

    /**
     * Refreshes the disabled state.
     */
    #refreshDisabled() {
        if ($.is(this.node, ':disabled')) {
            $.setAttribute(this.#inputs, { disabled: true });
        } else {
            $.removeAttribute(this.#inputs, 'disabled');
        }
    }

    /**
     * Renders the AuthCodeInput.
     */
    #render() {
        const containerOptions = {
            class: this.constructor.classes.container,
        };
        const direction = $.getAttribute(this.node, 'dir');

        if (direction) {
            containerOptions.attributes = { dir: direction };
        }

        this.#container = $.create('div', containerOptions);
        this.#inputs = [];

        const inputMode = $.getAttribute(this.node, 'inputmode') ||
            (this.options.regExp === '[0-9]' ? 'numeric' : 'text');
        const required = $.is(this.node, ':required');
        const inheritedAttributes = Object.fromEntries(
            [
                'aria-describedby',
                'aria-errormessage',
                'aria-invalid',
                'aria-required',
                'readonly',
            ]
                .map((attribute) => [
                    attribute,
                    $.getAttribute(this.node, attribute),
                ])
                .filter(([, value]) => value !== null),
        );

        let inputIndex = 0;

        for (const [segmentIndex, length] of this.#segments.entries()) {
            if (segmentIndex > 0) {
                const divider = $.create('span', {
                    class: this.constructor.classes.divider,
                });
                $.append(this.#container, divider);
            }

            for (let i = 0; i < length; i++) {
                const attributes = {
                    ...inheritedAttributes,
                    'type': 'text',
                    'maxlength': 1,
                    'size': 1,
                    'pattern': this.options.regExp,
                    'inputmode': inputMode,
                    'autocomplete': inputIndex ? 'off' : 'one-time-code',
                    'aria-label': this.options.getAriaLabel(++inputIndex),
                };

                if (required) {
                    attributes.required = '';
                }

                const formInput = $.create('div', {
                    class: this.constructor.classes.inputContainer,
                });
                const input = $.create('input', {
                    class: [
                        `input-${this.options.style}`,
                        this.constructor.classes.input,
                    ],
                    attributes,
                });

                $.append(formInput, input);
                this.#inputs.push(input);
                $.append(this.#container, formInput);
            }
        }

        $.addClass(this.node, this.constructor.classes.hide);
        $.setAttribute(this.node, { tabindex: -1 });
        $.before(this.node, this.#container);
    }

    /**
     * Updates the underlying input value.
     * @param {{notify?: boolean}} [options] Whether to emit a change event and allow automatic submission.
     */
    #updateValue({ notify = true } = {}) {
        const newValue = this.#inputs
            .map((node) => $.getValue(node))
            .join('');
        const lastIndex = this.#inputs.findLastIndex((input) => $.getValue(input));

        for (const [index, input] of this.#inputs.entries()) {
            if (index && index > lastIndex + 1) {
                $.setAttribute(input, { tabindex: -1 });
            } else {
                $.removeAttribute(input, 'tabindex');
            }
        }

        if (newValue === this.getValue()) {
            return;
        }

        $.setValue(this.node, newValue);

        if (!notify) {
            return;
        }

        $.triggerEvent(this.node, 'change.ui.authcodeinput');

        if (!this.node) {
            return;
        }

        if (
            this.#form &&
            this.options.autoSubmit &&
            newValue.length === this.#length &&
            newValue === this.getValue()
        ) {
            this.#form.requestSubmit();
        }
    }
}
